let renderFn = () => {};
let gen = 0;
export const setRender = (fn) => { renderFn = fn; };
export const render = () => { gen++; return renderFn(); };
// Асинхронный экран после await проверяет, что за это время не начался другой рендер
export const ticket = () => { const g = gen; return () => g === gen; };

export function go(tab) {
  state.tab = tab;
  state.flow = null;
  state.catId = null;
  render();
}

export function openInfo(item) {
  state.info = item;
  render();
}

export function openEdit(item) {
  state.info = null;
  const rub = item.amount / 100;
  Object.assign(state, {
    flow: 'add',
    edit: item,
    amt: (Number.isInteger(rub) ? String(rub) : rub.toFixed(2)).replace('.', ','),
    cat: item.category,
    kind: item.type === 'in' ? 'in' : 'out',
    note: item.note || '',
    catQuery: '',
    date: item.ts,
  });
  render();
}

// Повторить операцию: сумма, категория и комментарий те же, дата — сегодня; сохраняет сам пользователь
export function openRepeat(item) {
  openEdit(item);
  Object.assign(state, { edit: null, flow: 'category', date: Date.now() });
  render();
}

export function openCategory(id) {
  state.catId = id;
  state.flow = 'cat';
  render();
}

export function openAdd() {
  Object.assign(state, { flow: 'add', edit: null, amt: '', cat: null, note: '', catQuery: '', date: Date.now(), kind: 'out' });
  render();
}

// Свои диалоги: в PWA на iOS нативные confirm/prompt не работают
export function dialog({ title, text = '', ok = 'ОК', cancel = 'Отмена', danger = false, input = null }) {
  return new Promise((resolve) => {
    const wrap = document.createElement('div');
    wrap.className = 'modal-wrap';
    wrap.innerHTML = `
      <div class="modal-bd"></div>
      <div class="modal" role="dialog" aria-modal="true" aria-labelledby="mt">
        <h3 id="mt">${esc(title)}</h3>
        ${text ? `<p>${esc(text)}</p>` : ''}
        ${input ? `<input class="field" id="mi" type="${input.type || 'text'}" inputmode="${input.mode || 'text'}"
          placeholder="${esc(input.placeholder || '')}" value="${esc(input.value || '')}" autocomplete="off" autocapitalize="none">` : ''}
        <div class="modal-btns">
          <button class="btn alt" data-r="0">${esc(cancel)}</button>
          <button class="btn${danger ? ' danger-btn' : ''}" data-r="1">${esc(ok)}</button>
        </div>
      </div>`;
    document.body.appendChild(wrap);
    const field = wrap.querySelector('#mi');
    const back = document.activeElement;
    const close = (val) => {
      wrap.remove();
      document.removeEventListener('keydown', keys, true);
      back?.focus?.();
      resolve(val);
    };
    // Escape закрывает, Tab не выходит за пределы окна
    const keys = (e) => {
      if (e.key === 'Escape') { e.preventDefault(); close(null); }
      if (e.key === 'Tab') {
        const f = [...wrap.querySelectorAll('input, button')];
        const i = f.indexOf(document.activeElement);
        if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); }
        else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); }
      }
    };
    document.addEventListener('keydown', keys, true);
    wrap.querySelector('.modal-bd').onclick = () => close(null);
    wrap.querySelectorAll('[data-r]').forEach((b) => {
      // «Отмена» — false (для поля ввода null), закрытие фоном или Escape — всегда null
      b.onclick = () => (b.dataset.r === '0' ? close(input ? null : false) : close(input ? field.value : true));
    });
    field?.addEventListener('keydown', (e) => { if (e.key === 'Enter') wrap.querySelector('[data-r="1"]').click(); });
    setTimeout(() => (field || wrap.querySelector('[data-r="1"]')).focus(), 60);
  });
}

export const ask = (title, text, ok = 'Удалить') => dialog({ title, text, ok, danger: true });
export const askText = (title, opts = {}) => dialog({ title, ok: 'Готово', input: { ...opts } });

let toastTimer;
export function toast(text, undo) {
  const el = document.getElementById('toast');
  el.innerHTML = `<span>${esc(text)}</span>${undo ? '<button>Отменить</button>' : ''}`;
  el.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => (el.hidden = true), 4000);
  if (undo) el.querySelector('button').onclick = () => { el.hidden = true; undo(); };
}

export function tabbar() {
  const item = (id, label, icon) =>
    `<button class="tab${state.tab === id && !state.flow ? ' on' : ''}" data-tab="${id}">${icon}<span>${label}</span></button>`;
  return `<nav class="tabbar">
    ${item('home', 'Главная', icons.home)}
    ${item('charts', 'Графики', icons.chart)}
    <button class="tab add" data-tab="add" aria-label="Добавить операцию">${icons.plus}</button>
    ${item('budget', 'Бюджет', icons.budget)}
    ${item('deposits', 'Вклады', icons.safe)}
  </nav>`;
}

export function bindTabs() {
  app.querySelector('.tabbar')?.addEventListener('click', (e) => {
    const t = e.target.closest('.tab');
    if (!t) return;
    haptic();
    t.dataset.tab === 'add' ? openAdd() : go(t.dataset.tab);
  });
}

export const SKINS = [
  ['#f3f0ff', '#b9b2d6', '#5b5670'], ['#ffe9d6', '#e0a97a', '#6b4b33'], ['#d9f2ff', '#78b6d8', '#2f4e63'],
  ['#e4ffe9', '#86c99a', '#33543f'], ['#ffe2ec', '#dd8aa6', '#60374a'], ['#fff6cf', '#d8bd6a', '#5e5128'],
  ['#e8e8ec', '#9a9aa6', '#45454f'], ['#e6e2ff', '#9b8ae0', '#403565'], ['#d8fbf4', '#6fc3b4', '#2b5149'],
  ['#ffd9d9', '#e08585', '#5f3030'], ['#dfe7ff', '#8a9ce0', '#353f66'], ['#f1e0ff', '#b98ade', '#4c3566'],
];
export const avatar = () => localStorage.getItem('avatar') || '';
export const avatarSkin = () => Number(localStorage.getItem('avatarSkin') || 0);

export const skinStyle = (n) => {
  const [a, b, c] = SKINS[n % SKINS.length];
  return `background:radial-gradient(62% 56% at 32% 26%, ${a} 0%, ${b} 46%, ${c} 100%)`;
};

export function applySkin(n = avatarSkin()) {
  const [a, b, c] = SKINS[n % SKINS.length];
  const r = document.documentElement.style;
  r.setProperty('--skin-a', a);
  r.setProperty('--skin-b', b);
  r.setProperty('--skin-c', c);
}

export function avatarHTML(cls = '') {
  const src = avatar();
  if (src) return `<span class="ava photo ${cls}" style="background-image:url(${src})"></span>`;
  return `<span class="ava ${cls}" style="${skinStyle(avatarSkin())}"></span>`;
}

// плавный счётчик для крупных чисел
export function countUp(el, to) {
  if (!el) return;
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) { el.textContent = money(to); return; }
  const dur = 620;
  const start = performance.now();
  const step = (now) => {
    const p = Math.min(1, (now - start) / dur);
    el.textContent = money(Math.round(to * (1 - (1 - p) ** 3)));
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
